using System.Text.Json;

namespace Eam.Core.Servers;

/// <summary>
/// Satisfactory: the settings EAM applies itself (max players at launch, join password through the HTTPS API).
/// The admin password is the server's <see cref="ServerDefinition.TelnetPassword"/>, generated by EAM, used to claim it.
/// </summary>
public static class SatisfactoryConfig
{
    public sealed class Settings
    {
        public int MaxPlayers { get; set; } = 8;
        public string Password { get; set; } = "";
        /// <summary>True once EAM claimed the server (set its admin password) through the API.</summary>
        public bool Claimed { get; set; }
    }

    private static readonly JsonSerializerOptions Json = new() { WriteIndented = true, PropertyNamingPolicy = JsonNamingPolicy.CamelCase, PropertyNameCaseInsensitive = true };

    public static Settings Load(ServerDefinition def)
    {
        try { return File.Exists(def.SatisfactorySettingsFile) ? JsonSerializer.Deserialize<Settings>(File.ReadAllText(def.SatisfactorySettingsFile), Json) ?? new() : new(); }
        catch (JsonException) { return new(); }
    }

    public static void Save(ServerDefinition def, Settings s)
    {
        Directory.CreateDirectory(def.EamDir);
        File.WriteAllText(def.SatisfactorySettingsFile + ".tmp", JsonSerializer.Serialize(s, Json));
        File.Move(def.SatisfactorySettingsFile + ".tmp", def.SatisfactorySettingsFile, overwrite: true);
    }
}
